  FT["PH-H3096"] = {"id":"PH-H3096","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3660_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第3207号共和国法（即《授予圣费尔南多电灯电力公司在邦板牙省圣费尔南多市镇经营电灯、热力与电力系统特许权》）的法案","en":"An Act to Amend Republic Act Numbered Thirty-Two Hundred Seven, Entitled “An Act Granting the San Fernando Electric Light and Power Co., Inc. a Franchise for an Electric Light, Heat and Power System in the Municipality of San Fernando, Province of Pampanga”","orig":"An Act to Amend Republic Act Numbered Thirty-Two Hundred Seven, Entitled “An Act Granting the San Fernando Electric Light and Power Co., Inc. a Franchise for an Electric Light, Heat and Power System in the Municipality of San Fernando, Province of Pampanga”"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 3660","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3660_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3096-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act Numbered Thirty-two hundred seven is hereby amended by inserting between sections two and three thereof the following new section:\n\"Sec. 2-A. In consideration of the franchise and rights hereby granted, the grantee shall pay into the Treasury of the Philippines a franchise tax equal to two per centum of the gross earnings for electric current sold under this franchise. Provision of laws to the contrary notwithstanding, the franchise tax equal to two per centum of the gross earnings of the grantee shall be respected. Effective upon the date the original franchise was granted, no other tax upon its capital stock, franchise, right of way, earnings and all other property owned or operated by the grantee under this concession or franchise shall be levied or assessed on the herein grantee except the franchise tax of two per centum of the gross earnings mentioned in the said original franchise.\""}},{"id":"PH-H3096-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1963."}}],"pack":"ph-p44","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Thirty-Two Hundred Seven, Entitled “An Act Granting the San Fernando Electric Light and Power Co., Inc. a Franchise for an Electric Light, Heat and Power System in the Municipality of San Fernando, Province of Pampanga”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3097"] = {"id":"PH-H3097","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3661_1963.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"设立菲律宾科学高中的法案","en":"An Act to Establish the Philippine Science High School","orig":"An Act to Establish the Philippine Science High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3661","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-22","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3661_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3097-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a high school to be known as the \"Philippine Science High School.\""}},{"id":"PH-H3097-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The purpose of the said high school shall be to offer on a free scholarship basis a secondary course with special emphasis on subjects pertaining to the sciences with the end in view of preparing its students for a science career."}},{"id":"PH-H3097-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The head of this high school shall be known as the Director of the Philippine Science High School. He shall be appointed by the Chairman subject to the approval and his compensation shall be fixed by, the Board of Trustees. He shall not be removed therefrom except for the cause. His functions, powers and duties, in addition to those specifically provided for in this Act, shall be those usually pertaining to the office of the principal of a public high school."}},{"id":"PH-H3097-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Philippine Science High School shall have the general powers set out in Section thirteen of Act Numbered Fourteen hundred and fifty-nine, as amended, and the exercise of its corporate powers is hereby vested exclusively in the Board of Trustees and in the Director of the High School insofar as authorized by said Board.\nThe Board of Trustees shall be composed of the Chairman of the National Science Development Board, who shall be ex officio Chairman of the Board, the Secretary of Education, who shall be ex officio Vice-Chairman, and the following members; the President of the University of the Philippines, the Chairman of the UNESCO National Commission of the Philippines, the President of the Science Foundation of the Philippines, the Director of the Philippine Science High School, all as ex officio members representative from the American-Philippine Science Foundation, Inc., to be designated by its President, two representatives from scientific and technological associations or societies, one member representing industry and one member representing agriculture. All the members who are not receiving regular compensation from the government shall receive a per diem of fifty pesos each per session of the Board.\nThe members of the Board representing scientific and technological associations or societies, industry, and agriculture shall be appointed by the President of the Philippines upon recommendation of the Chairman of the Board of Trustees. Two of them shall serve for six years, one for four years, and one for two years.\nThe Vice-Chairman of the National Science Development Board and the Undersecretary of Education shall, in the absence of the heads of their respective agencies, act as ex officio Chairman and ex officio Vice-Chairman of the Board of Trustees, respectively."}},{"id":"PH-H3097-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Board of Trustees shall exercise for the Philippine Science High School all the powers and prerogatives of a board of directors of a private corporation. It shall also have the following powers and duties:\n(a) To fix the site of the Science High School;\n(b) To receive and appropriate to the ends specified by law such sums as may be provided by law for the support of the High School;\n(c) To approve appointments made and contracts entered into by the Director in connection with the employment of professors, instructors, lecturers, and other employees of the school, subject to the provisions of Section eleven of this Act; to fix their compensation and other conditions of employment; and to remove them for cause after an investigation and hearing shall have been had;\n(d) To approve the curricula, course of study, and rules of discipline drawn up by the Executive Council as herein-after provided;\n(e) To provide fellowship for faculty members and approve the grant of scholarships, stipends and such other allowances to deserving students;\n(f) To approve the issuance of certificates or diplomas to successful candidates for graduation;\n(g) To provide its own rules of procedure, and to prescribe for the administration of the High School such general rules and regulations, not contrary to law, as are consistent with the purpose of the High School, as defined in Section two of this Act;\n(h) To receive in trust legacies, gifts, and donations of real and personal property of all kinds and to administer the same in accordance with the directions and instructions of the donor, and, in default thereof, in such manner as the Board of Trustees may in its discretion determine, for the benefit of the High School or for aid to any of its students; and\n(i) To establish the criteria for the selection and admission of students which shall include, among others, national competitive examinations."}},{"id":"PH-H3097-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members holding office at the time the meeting of the Board is called. All processes against the Board of Trustees shall be served on the Director or secretary thereof."}},{"id":"PH-H3097-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"On or before the fifteenth of June of each year, the Board of Trustees shall file with the President and Congress of the Philippines a detailed report, setting forth the progress, condition, and needs of the High School."}},{"id":"PH-H3097-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"There shall be an Executive Council consisting of the Director, the heads of departments, and such other ranking faculty members or officials of the High School as may be determined by the Director. The Council shall have power to screen and select the students to be admitted to the High School; to select students who shall be recipients of scholarships, stipends and other allowances; and to develop the curricula, course of study, and rules of discipline, all subject to the approval of the Board. The Council shall have the exclusive power to recommend students eligible for graduation. Through the Director it shall have disciplinary power over the students. The Council shall implement and execute the policies laid down by the Board of Trustees and exercise such other functions, powers and duties as the Board may prescribe."}},{"id":"PH-H3097-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"There shall be a registrar of the High School who shall also act as Secretary of the Board, to be appointed by the Director with the approval of the Board of Trustees. He shall keep such records as may be prescribed by the Board."}},{"id":"PH-H3097-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"There shall be a treasurer of the Philippine Science High School who shall be appointed by the Director with the approval of the Board of Trustee. All accounts and expenses shall be audited by the Auditor General or his duly authorized representative."}},{"id":"PH-H3097-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Professors, instructors and other faculty members of the High School shall be exempt as such from any civil service examination or regulations as a requisite to appointment. They shall be selected in accordance will such criteria as may be established by the Board of Trustees which shall include, if necessary and practicable, screening and competitive examination. Said professors, instructors and faculty members, as well as the school’s administrative staff, shall be exempt from the provisions of laws, rules and regulations on wage and position classification."}},{"id":"PH-H3097-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"All legacies, gifts and donations for the benefit of the High School or for its support and maintenance or for aid to any of its students shall be tax-exempt and shall be an allowable deduction from the gross income of donors. For the purpose of the income tax, the High School shall be exempt from the payment of all taxes, fees, assessments and other charges of the Government, its branches and subdivisions."}},{"id":"PH-H3097-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"All incomes and donations to the High School created under this Act shall constitute a special fund to be known as a Science High School Fund. This fund shall be expended by the Board of Trustees exclusively for the purpose of this Act."}},{"id":"PH-H3097-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Heads of bureaus or offices of the National Government are hereby authorized to loan or transfer, upon request of the Director of the High School, such apparatus, supplies and other properties as may be needed by the High School, and to detail employees for duty therein, when in the judgment of the head of the bureau or office, they can be spared without serious detriment to the public service. Employees so detailed shall perform such duties as are required under such detail, and the time employed shall be counted as part of their regular official hours, all laws, rules or regulations limiting the detail of government employees notwithstanding.\nAny officer, or employee of the Government engaged as lecturer in the High School, may receive a compensation in addition to his salary at the rate to be fixed by the Board: Provided, That his duties as such lecturer are performed outside of the regular office hours."}},{"id":"PH-H3097-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"To carry out the purpose of this Act, including the operation of the High School, the acquisition, improvement, and conditioning of the land on which the High School shall be located, the construction, maintenance, and repair of buildings and improvements, and the acquisition of furniture, fixtures and equipment, the sum of nine million seven hundred forty thousand pesos is hereby appropriated out of any funds in the National Treasury not otherwise appropriated. Said sum shall be released for expenditure in amounts on the date hereinbelow set forth:\nUpon approval of this Act, for the purposes above-mentioned ...\nP4,700,000 00 On July 1, 1963 300,000 00 On July 1, 1964 350,000.00 On July 1, 1965 470,000.00 On July 1, 1966 560,000.00 On July 1, 1967 560,000.00 On July 1, 1968 560,000.00 On July 1, 1969 560,000.00 On July 1, 1970 560,000.00 On July 1, 1971 560,000.00 On July 1, 1972 560,000.00 Total P9,740,000.00 Thereafter, the expenses of the High School, for the purposes above-described, shall be provided in the yearly General Appropriation Acts of the National Government: Provided, however, That any unexpended balance for any shall also form part of the aforementioned Science High School Fund."}},{"id":"PH-H3097-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"If any provision of this Act or the application of such provision to any person or circumstance is held invalid, the remainder of this Act or the application of such provision to other persons or circumstances shall not be affected thereby."}},{"id":"PH-H3097-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"All laws, rules and orders inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H3097-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 22, 1963."}}],"pack":"ph-p44","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish the Philippine Science High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3098"] = {"id":"PH-H3098","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3662_1963.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":"授予 Republic Telephone Company, Incorporated 在菲律宾各省、市、镇之间以及国际与国内通信线路及站点安装、运营和维护电话系统的特许经营权法案","en":"An Act Granting the Republic Telephone Company, Incorporated, a Franchise to Install, Operate and Maintain Telephone Systems in and Between the Provinces, Cities and Municipalities in the Philippines and Circuits and/or Stations for International and Domestic Communications","orig":"An Act Granting the Republic Telephone Company, Incorporated, a Franchise to Install, Operate and Maintain Telephone Systems in and Between the Provinces, Cities and Municipalities in the Philippines and Circuits and/or Stations for International and Domestic Communications"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 3662","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-22","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3662_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3098-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and of Commonwealth Act Numbered One hundred forty-six, as amended, there is hereby granted to the Republic Telephone Company, Incorporated, hereinafter called the grantee, its successors or assigns, for a period of fifty years from the approval of this Act, the right, privilege, and authority to construct, maintain and operate telephone systems in Cabanatuan City and Lipa City; Calamba, Santa Cruz, Santa Rosa, Cabuyao, Los Baños, Pagsanjan and Lumban, Province of Laguna; Batangas, Tanauan and Bauan, Province of Batangas; Pasig and Antipolo, Province of Rizal; Balanga, Province of Bataan; and Malolos and Baliuag, Province of Bulacan; and in and between the provinces, cities and municipalities in the Philippines, it being understood that the grantee is authorized to construct, operate and maintain such exchanges and branch tributary lines within the provinces, cities and municipalities traversed to connect with the main systems, as public interest may warrant. The grantee is authorized to carry on the business of the electrical transmission of messages, impressions, pictures and signals in and between said provinces, cities and municipalities in the Philippines, and/or to connect such systems within the Philippines to the telephone systems of other countries, and for the purpose of operating said telephone systems and transmitting messages and signals by means of electricity, to construct, maintain, and operate and use all apparatus, conduits, appliances, receivers, transmitters, antennas, and equipment necessary for the electrical transmission of messages and signals, and to erect poles, structures, string wires, build conduits, lay cables, and to construct, maintain and use such other approved and general accepted means of electrical conduction in, on, over, or under the public roads, government right-of-ways, lands, bridges, rivers, waters, streets, lanes and sidewalks of said provinces, cities and municipalities, and overhead or underground or submarine lines or on the surface of the ground, as may be necessary and best adapted to said transmission: Provided, however, That all cables laid, all poles erected and all conduits constructed or used by the grantee, its successors or assigns, shall be located in places designated by the Secretary of Public Works and Communications and poles shall be erected in a workmanlike manner to the satisfaction of said official: And Provided, further, That upon reasonable notice of the Secretary of Public Works and Communications the grantee, its successors or assigns may be required to relocate poles or remove or raise wires or other conductors so as to permit the passage of buildings or other structures from one place to another, one-half the actual cost of such relocation of poles or raising or removal of wires or other conductors to be paid by the person at whose instance the building or structures is moved; and, at the expense of the grantee, its successors or assigns, to relocate conduits, poles, and wires and to remove or raise wires or other conductors when the Secretary of Public Works and Communications so orders and when public interest so requires: Provided, finally, That from any order to relocate conduits, poles or wires, or to raise or remove wires or other conductors, the said grantee, its successors or assigns, shall have the right to appeal to the President of the Philippines, whose decision in the matter shall be final.\nShould the grantee, its successors or assigns, fail, refuse, or neglect within a period of ninety days after notice to relocate its poles, conduits, wires, or other conductors, or to raise its wires or other conductors when so directed by the Secretary of Public Works and Communications then this official may relocate said poles, conduits, wires, or other conductors or raise said wires or other conductors at the expense of the grantee, its successors or assigns: Provided, That the installation of all instruments, inside wiring, and all outside construction work shall be done in accordance with the rules and regulations, prescribed by the Secretary of Public Works and Communications: Provided, further, That whenever twenty-five or more pairs of wires or other conductors are carried on in one line of poles in any city or municipal center, said wires or conductors shall be placed in one cable and that whenever more than one thousand two hundred twelve pairs of wires or other conductors are carried on one line of poles, said cables shall be placed underground by the grantee, its successors or assigns, whenever ordered so to do by the Secretary of Public Works and Communications: Provided, further, That the poles erected, wires and cables strung, or conduit laid by virtue of this franchise shall be so placed as not to impair the efficient and effective transmission of messages or signals by any other company where poles are erected, whose wires and cables are strung, or whose conduits are actually laid at the time that poles are to be erected, wires and cables strung and conduits laid under and by virtue of this franchise: And Provided, finally, That poles erected by the grantee shall be of such a height as to maintain the wire stretched on the same at a height of at least ten feet above the level of the ground providing a height of at least fifteen feet in crossing roads or streets, and shall be placed so as not to be a danger to public safety, in accordance with a plan approved by the Secretary of Public Works and Communications."}},{"id":"PH-H3098-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee may install, maintain, and operate radio-telephone equipment to furnish an economical medium of telephonic communications in and between the provinces, cities and municipalities mentioned in Section one of this Act and between the telephone systems of other franchise grantees and between the Philippine telephone systems and those of other countries: Provided, That the location, installation or operation of such radio-telephonic equipment must be previously approved by the President of the Philippines upon recommendation of the Secretary of Public Works and Communications: And Provided, further, That the Secretary of Public Works and Communications, subject to the approval of the President of the Philippines, shall have the authority to supervise and regulate the installation or operation of such radio-telephone equipment. The privilege to install, maintain and operate radio-telephonic equipment shall not be construed to authorize the broadcasting of any commercial message, or the transmission of any message for hire by radio-graphic equipment or the transmission of radio-telegraphic messages for hire."}},{"id":"PH-H3098-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall supply telephone service in said provinces, cities and municipalities mentioned in Section one where it may have established a local telephone exchange to any applicant for the same, within thirty days after the date of their applications, and as between such applicant and other like applicants, in the order of the date of their applications, up to the limit of the capacity of the telephone system of said grantee, to be determined by the Public Service Commission on the application of such grantee and should the demand for telephone service at any time increase beyond the capacity of the telephone system of said grantee to supply the same, the capacity of said telephone system shall be increased by said grantee to meet such demand, in accordance with the decision of the Public Service Commission or its legal successor: Provided, That in case the point at which the telephone service is to be supplied is more than fifty meters from the local exchange lines operated by said grantee, the latter shall not be obliged to furnish said service, unless the applicant for telephone service defrays the actual expenses for the poles and wires and installation thereof necessary for such service and in such cases the Public Service Commission may extend the time within which the grantee must furnish such service beyond the said period of thirty days."}},{"id":"PH-H3098-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"For the purpose of erecting and maintaining poles or other supports for said wires or other conductors or for the purpose of laying and maintaining underground said wires, cables, or other conductors, it shall be lawful for the grantee, its successors or assigns, with the prior approval of the Secretary of Public Works and Communications, to make excavations or lay conduits in any of the public places, highways, streets, lanes, alleys, avenues, sidewalks, or bridges of said provinces, cities and municipalities: Provided, However, That any public place, highway, street, lane, alley, avenue, sidewalk or bridge disturbed, altered, or changed by reason of the erection of poles or other supports, or the laying underground of wires, or other conductors, or of conduits shall be repaired and replaced in a workmanlike manner by said grantee, its successors or assigns, to the satisfaction of the Secretary of Public Works and Communications. Should the grantee, its successors or assigns, after ten days notice from said authority, fail, refuse, or neglect to replace any part of a public place, road, highway, street, lane, alley, avenue, sidewalk or bridge altered, changed, or disturbed by said grantee, its successors or assigns, then the Secretary of Public Works and Communications, shall have the right to have the same repaired and place in good order and condition at the cost and expense of the grantee, its successors or assigns."}},{"id":"PH-H3098-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All telephone lines and systems for the transmission of messages and signals owned, maintained, or operated by the grantee, its successors or assigns, shall be operated and maintained at all times in a satisfactory manner, and its shall be the further duty of said grantee, its successors or assigns, whenever required to do so by the Public Service Commission, to modify, improve, and change such telephone system or systems, for the transmission of messages and signals by means of electricity, in such manner and to such extent as the progress of science and improvements in the method of transmission of messages and signals by means of electricity may make reasonable and proper."}},{"id":"PH-H3098-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the telephone and electrical transmission business and shall furnish to the Auditor General and the Treasurer of the Philippines a copy of such account not later than the thirty-first day of July of each year for the twelve months preceding the first day of July."}},{"id":"PH-H3098-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall be liable to pay the same taxes on its real estate, buildings, and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition, the grantee, its successors or assigns, shall pay to the Treasurer of the Philippines each year, within ten days after the audit and approval of the accounts as prescribed in Section six of this Act, two per centum of all gross receipts of the telephone or other electrical transmission business transacted under this franchise by the grantee, its successors or assigns, and the said percentage shall be in lieu of all other taxes."}},{"id":"PH-H3098-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not begin any construction whatever pursuant to this franchise without first obtaining a Certificate of Public Necessity and Convenience from the Public Service Commission, of the form and character provided for in Commonwealth Act Numbered One hundred and forty-six, as amended, specifically authorizing such construction. The grantee shall not exercise any right or privilege under this franchise without first having obtained such Certificate of Public Necessity and Convenience from the Public Service Commission. The Public Service Commission shall have the power to issue such Certificate of Public Necessity and Convenience whenever it shall, after due hearing, determine that such construction, or such exercise of the right, privilege or franchise, is necessary and proper for the public convenience; and the Commission shall have the power in so approving to impose such conditions as to construction, equipment, maintenance, service or operation as the public convenience and interest may reasonably require, and such certificate shall state the date that the grantee commences construction work and the period within which the work shall be completed. In order to avail itself of the rights granted by such Certificate of Public Necessity and Convenience the grantee must file with the Public Service Commission, within such period as said Commission shall fix, its acceptance in writing of the terms and conditions of said certificate, together with the document evidencing the fact that the deposit required by said certificate has been made. In the event that the grantee shall not commence the furnishing of telephone service referred to in the certificate obtained and filed as herein provided within such period as the Public Service Commission shall have fixed, deposits made pursuant to Section nine of this Act shall be forfeited to the National Government unless the grantee shall have been prevented from doing so by an act of God, force majeure, usurpation by military power, martial law, riot, uprising, or other cause beyond its control: Provided, However, That if the grantee shall have been so prevented by one or more or all of such causes from commencing to furnish telephone service within the period specified, the time during which it shall have been so prevented shall be added to said period."}},{"id":"PH-H3098-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall be required by the Public Service Commission for each Certificate of Public Necessity and Convenience obtained by it subsequent to the date of this Act, to make within such period as the said Commission shall fix, a deposit of not less than ten thousand pesos, Philippine currency, or negotiable bonds of the Government of the Philippines, or other securities approved by the Public Service Commission, of the par value of not less than ten thousand pesos, Philippine currency, in the National Treasury as a guaranty of good faith that the grantee, within the period also specified by the Public Service Commission, shall commence and terminate the necessary work and shall be provided with all the equipment necessary to commence furnishing telephone service in the corresponding province, city or municipality. The Public Service Commission shall order the return of the deposit hereby required to the grantee upon the termination of the work for the furnishing of telephone service in accordance with the terms and conditions of the certificate obtained, and the Treasurer of the Philippines shall return said deposit immediately upon presentation to him of a certified copy of the order of the Public Service Commission."}},{"id":"PH-H3098-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Within forty days after the approval of this Act, the grantee shall file with the Secretary of Public Works and Communications its written acceptance of this franchise and of all the terms and conditions hereof, and in default of such acceptance, within the time so limited, this franchise shall become null and void."}},{"id":"PH-H3098-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The granting of this franchise takes cognizance of the fact that on its date of issuance the grantee is providing telephone exchange service under the authority of Certificates of Public Convenience and Necessity issued by the Public Service Commission of the Philippines at all locations named in Section one hereof and further that the grantee had previously installed properties having a value substantially in excess of one million pesos and further that financial responsibility and intent of performing under the obligations specified hereunder had thereby been established."}},{"id":"PH-H3098-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the district auditors or their authorized representatives and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts and the net receipts for the quarter past and the general condition of the business."}},{"id":"PH-H3098-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The rights herein granted shall not be exclusive, and the rights and power to grant to any corporation, association or person other than the grantee, franchise for the telephone or electrical transmission of messages or signals shall not be impaired or affected by the granting of this franchise: Provided, That the poles or antennas erected, wires strung or cables or conduits laid by virtue of any franchise for telephone, or other electrical transmission of messages and signals granted subsequent to this franchise shall be so placed as not to impair the efficient and effective transmission of messages or signals under this franchise by means of poles or antennas erected, wires strung, or cables or conduits actually laid and in existence at the time of the granting of said subsequent franchise: And Provided, further, That the Public Service Commission, after hearing both parties interested, may compel the grantee of this franchise or its successors or assigns to remove, relocate, or replace its poles, wires or conduits; but in such case the reasonable cost of the removal, relocation, or replacement shall be paid by the grantee of the subsequent franchise or his successors or assigns to the grantee of this franchise or its successors or assigns."}},{"id":"PH-H3098-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or persons, caused by the construction or operation of the telephone, radio-telephone or electrical transmission system of the said grantee, its successors or assigns."}},{"id":"PH-H3098-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"All rates for the telephone service, flat rates, toll rates as well as measured rates are subject to the approval of the Public Service Commission."}},{"id":"PH-H3098-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The grantee shall not, without the previous and explicit approval of the Congress of the Philippines directly or indirectly, transfer, sell, or assign this franchise to any person, association, company, or corporation or other mercantile or legal entity."}},{"id":"PH-H3098-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"The grantee may install, maintain, operate, purchase or lease such telephone stations, lines, cables or telecommunication system, as is, or are, convenient or essential to efficiently carry out the purpose of this franchise: Provided, However, That the grantee, its successors or assigns, shall not, without the permission of the Public Service Commission first had, install, maintain, operate, purchase, or lease such stations, lines, cables, or systems."}},{"id":"PH-H3098-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The Philippine Government, including any and all of its departments and bureaus shall have the privilege, without compensation, of using such space on the poles of the grantee for wire attachments, cable attachments, or crossarm attachments as will not impair the public safety, employees safety, or service requirements of the grantee. Municipalities shall also have the privilege, without compensation, of using the poles of the grantee for local police and fire alarm systems under the same terms and conditions. If the requirements of the Philippine Government or of a municipality for the use of the grantee’s poles exceed the limitations named above in respect to public safety, employees safety, or service impairments, mutual arrangement may be entered into between the government entities and the grantee for pole replacements or other construction, the cost of said construction to be borne by the government entities or, if undertaken by the grantee, to be amortized on a basis of fair compensation to the grantee. In the case of disagreement as to pole replacement or other construction and/or compensation therefor or the absorption of cost the same shall be fixed by the Public Service Commission of the Philippines. Written request providing ninety-days advance notice of needs will be filed with the grantee in advance of any attachments by the Philippine Government or any municipality to grantee’s poles."}},{"id":"PH-H3098-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"The grantee, its successors or assigns, shall not issue stock or bonds under this franchise except in exchange for actual cash or property at a fair valuation equal to the market value of the stock or bonds so issued."}},{"id":"PH-H3098-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"This franchise is granted with the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and that all public lands or rights of use or occupation of lands secured by virtue of this franchise shall revert upon its termination, revocation or nullification to the national, provincial or municipal governments which were the owners thereof on the date when this franchise was granted."}},{"id":"PH-H3098-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"The grantee agrees that in the event the Philippine Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and Certificates of Public Necessity and Convenience in the aforesaid territory and will turn over to the government all serviceable equipment at replacement cost, less depreciation to be fixed by the Public Service Commission."}},{"id":"PH-H3098-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Wherever in this franchise the term \"grantee\" is used, it shall be held and understood to mean and represent the \"Republic Telephone Company, Incorporated,\" its representative, successors or assigns."}},{"id":"PH-H3098-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1963."}}],"pack":"ph-p44","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Republic Telephone Company, Incorporated, a Franchise to Install, Operate and Maintain Telephone Systems in and Between the Provinces, Cities and Municipalities in the Philippines and Circuits and/or Stations for International and Domestic Communications","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3099"] = {"id":"PH-H3099","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3663_1963.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"通过修订第 537 号共和国法（即 Quezon 市修正宪章）若干条款，设立市各部门助理首长职位并统一 Quezon 市官员薪金的法案","en":"An Act Creating the Positions of Assistant Chiefs of Departments and Standardizing the Salaries of the City Officials of Quezon City, by Amending Certain Sections of Republic Act Numbered Five Hundred and Thirty-Seven, Otherwise Known as the Revised Charter of Quezon City","orig":"An Act Creating the Positions of Assistant Chiefs of Departments and Standardizing the Salaries of the City Officials of Quezon City, by Amending Certain Sections of Republic Act Numbered Five Hundred and Thirty-Seven, Otherwise Known as the Revised Charter of Quezon City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3663","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-22","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3663_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3099-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eight of Republic Act Numbered Five hundred and thirty-seven, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"Sec. 8. The Mayor— His compensation. -The Mayor shall be the chief executive of the City, and as such shall have immediate supervision and control over the executive functions of the different departments subject to the supervision of the proper head of department. He shall receive a salary of fifteen thousand pesos per annum. The City Council may provide the Mayor in addition to his salary a commutable quarters allowance of not more than three thousand pesos per annum.\"\nThere shall be a secretary to the Mayor who shall have the rank of assistant chief of a department, with a salary of eight thousand four hundred pesos per annum."}},{"id":"PH-H3099-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The last paragraph of Section nine of the same Act, as amended by Republic Act Numbered Twenty-six hundred and forty-nine, is further amended to read as follows:\n\"He shall receive a salary of twelve thousand pesos per annum.\""}},{"id":"PH-H3099-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The last paragraph of Section eleven of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"The eight councilors hereinabove mentioned shall be elected as provided for by existing law; and such councilors shall receive a fixed salary of ten thousand pesos per annum each.\""}},{"id":"PH-H3099-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section fifteen of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"Sec. 15. The city secretary— His compensation. -There shall be a city secretary. He shall receive a salary of eight thousand four hundred pesos per annum.\""}},{"id":"PH-H3099-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section twenty-one of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"Sec. 21. The General Auditing Office. -The Auditor General shall receive and audit all accounts of the City in accordance with the provisions of law relating to government accounts and accounting. The City Auditor shall be paid from the funds of the city at the rate of twelve thousand pesos per annum. There shall be an assistant city auditor who shall receive a salary of nine thousand pesos per annum. He shall perform the duties and exercise the powers of the City Auditor in the event of sickness, absence or other temporary incapacity of the City Auditor.\""}},{"id":"PH-H3099-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The first paragraph of Section twenty-four of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"Sec. 24. The City Engineer his powers, duties and compensation. -There shall be a city engineer who shall be in charge of the department of engineering. He shall receive a salary of twelve thousand pesos per annum. There shall be an assistant city engineer who shall receive a salary of nine thousand pesos per annum. He shall perform the duties and exercise the powers of the city engineer in the event of sickness, absence or other temporary incapacity of the city engineer. The city engineer shall have the following powers and duties:\""}},{"id":"PH-H3099-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The first paragraph of Section twenty-seven of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"Sec. 27. Powers and duties of the City Treasurer. -There shall be a city treasurer with a salary of twelve thousand pesos per annum, who shall have charge of the department of finance and shall act as chief fiscal officer and financial adviser of the city and custodian of its funds. There shall be an assistant city treasurer who shall receive a salary of nine thousand pesos per annum. He shall perform the duties and exercise the powers of the city treasurer in the event of sickness, absence or other temporary incapacity of the city treasurer. The city treasurer shall have the following general powers and duties:\""}},{"id":"PH-H3099-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section twenty-nine of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine is further amended to read as follows:\n\"Sec. 29. Compensation of City Fiscal and his assistants. -The City Fiscal and his assistants shall receive the salaries herein set forth, which shall be paid from the funds of the City:\n\"(a) City fiscal, at twelve thousand pesos per annum.\n\"(b) First assistant city fiscal, at ten thousand eight hundred pesos per annum.\n\"(c) Second assistant city fiscal, at ten thousand pesos per annum.\n\"(d) Two third assistant city fiscals, at nine thousand six hundred pesos per annum each.\n\"(e) Five fourth assistant city fiscals, at eight thousand four hundred pesos per annum each.\n\"(f) Five fifth assistant city fiscals at seven thousand eight hundred pesos per annum each.\n\"(g) Seven sixth assistant city fiscals, at six thousand pesos per annum each.\""}},{"id":"PH-H3099-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The last paragraph of Section thirty of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"The judges of the municipal court shall receive a salary of twelve thousand pesos per annum each.\""}},{"id":"PH-H3099-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The first paragraph of Section forty-two of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"Sec. 42. Powers and duties of the City Health Officer. -There shall be a city health officer with a salary of twelve thousand pesos per annum, who shall have charge of the health department. There shall be an assistant city health officer who shall receive a salary of nine thousand pesos per annum. He shall perform the duties and exercise the powers of the city health officer in the event of sickness, absence or other temporary incapacity of the city health officer. The city health officer shall have the following general powers and duties:\""}},{"id":"PH-H3099-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The first paragraph of Section forty-three of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"Sec. 43. The Chief of Police. -There shall be a Chief of Police with a salary of twelve thousand pesos per annum. There shall be a deputy chief of police who shall receive a salary of nine thousand pesos per annum. He shall perform the duties and exercise the powers of the chief of police in the event of sickness, absence or other temporary incapacity of the chief of police. The chief of police shall have the following general powers and duties.\""}},{"id":"PH-H3099-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section forty-five of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"Sec. 45. The City Assessor. -There shall be a City Assessor who shall have charge of the department of assessment. He shall receive a compensation of twelve thousand pesos per annum. There shall be an assistant city assessor who shall receive a salary of nine thousand pesos per annum. He shall perform the duties and exercise the powers of the city assessor in the event of sickness, absence or other temporary incapacity of the city assessor.\""}},{"id":"PH-H3099-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The first paragraph of Section sixty-five of the same Act, as amended by Republic Act Numbered Twenty-six hundred forty-nine, is further amended to read as follows:\n\"Sec. 65. Powers and duties of chief. -There shall be a chief of the fire department with a salary of twelve thousand pesos per annum. There shall be a deputy chief of the fire department who shall receive a salary of nine thousand pesos per annum. He shall perform the duties and exercise the powers of the chief in the event of sickness, absence or temporary incapacity of the chief of the fire department. The chief of the fire department shall have the following general powers and duties:\""}},{"id":"PH-H3099-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1963."}}],"pack":"ph-p44","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Positions of Assistant Chiefs of Departments and Standardizing the Salaries of the City Officials of Quezon City, by Amending Certain Sections of Republic Act Numbered Five Hundred and Thirty-Seven, Otherwise Known as the Revised Charter of Quezon City","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3100"] = {"id":"PH-H3100","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3664_1963.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在哥打巴托省设立Surallah市镇的法案","en":"An Act Creating the Municipality of Surallah in the Province of Cotabato","orig":"An Act to Amend Republic Act Numbered Thirty-Four Hundred Twenty, Entitled “An Act Creating the Municipality of Surallah in the Province of Cotabato”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3664","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3664_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3100-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Thirty-four hundred twenty is hereby amended to read as follows:\n\"Sec. 1. The barrios of Centrallah, Sinolon, New Dumangas, Veterans, Lake Sebu, Lambongtong, Solution, Lamian, Lamla-at, Lahit, Barrio Ten and Barrio Eleven (Libertad), including the sitios of Colongolo, Tubi-Ala, Bayabas, Head Sapali, Tabodtod, Nawan, Lacag, Kolon Bong, Laconon, Salacape, Bogad, North Seguil, Tabanlid, Lambod, Bacnob, Lamcade, San Jose, Dalag, Talihik Bac-alo, Datu Ligal, Datu Ba-oy, Lamlosok, Bacdolong, Tabawao, Tanon, Camoning, Head Ala, Lambilan, Maculan, Lamsogod, Buenavista, Canajay, Lamlako, San Francisco, Little Baguio, Lambosong, Tamsalon. Tacamsad, Lamhinik, Tucubo, Sla-Abon, Datal Kling, Head Sipaca, Lawa, South Kiantay, Siop, Moto Bantong, Moloy, Crossing Cabayo, Ila-elis, Datu Glam, Datu Godwino, Datu Ouel and Sala Banog, of Bañga, Cotabato, are separated from said municipality, and are constituted into a distinct and independent municipality to be known as the Municipality of Surallah, Province of Cotabato, with the seat of government at the present site of Barrio Ten and Barrio Eleven (Libertad) and the boundary of this new municipality shall be more particularly defined as follows:\n\"Beginning at a Point marked ‘1’ (intersection of National Highway, Allah-Marbel road and northeastern corner of Lot No. 601, PLS-214-D-9, Map of Bañga, Province of Cotabato);\n\"Thence, following the farm road in a southeasterly direction to Point ‘2’ (corner 3 of Lot No. 500, PLS-285-D, Barrio Cinco (5), Map of Bañga, Province of Cotabato);\n\"Thence, following the farm road in a soutwesterly direction to Point ‘3’ (corner 3 of Lot No. 563, PLS-285-D, Barrio Cinco (5), Map of Bañga, Province of Cotabato);\n\"Thence, following the farm road in a southeasterly direction to Point ‘4’ (corner 3 of Lot No. 548, PLS-285-D, Barrio Cinco (5), Map of Bañga, Province of Cotabato);\n\"Thence, following the farm road in a northeasterly direction to Point ‘5’ (southwestern corner of Lot No. 539, PLS-214-D-9, Map of Bañga, Province of Cotabato and northwestern corner of Lot No. 540. PLS-214-D-9, Map of Bañga, Province of Cotabato);\n\"Thence, in a southeasterly direction to Point ‘6’ (northeastern corner of Lot No. 555, PLS-214-D-9, Map of Bañga, Province of Cotabato);\n\"Thence, following the boundary of Bañga Settlement District (PLS-214-D-9, Project I-MSA-45) in a southwesterly direction to Point ‘7’ (intersection of PLS-214-D-9 and SWO-26589 on Lot No. 278, SWO-26589);\n\"Thence, following the Northwest, North and Northeast boundary of SWO-26589 to Point ‘8’ (corner ‘4’ of Lot No. 455, SWO-26589, Barrio Lamian, Municipality of Bañga, Province of Cotabato);\n\"Thence, to Point ‘9’ (Peak of Breast Peak);\n\"Thence, to Point ‘10’ (Peak of Mt. Malibato);\n\"Thence, to Point ‘11’ (Peak of Mt. Talompong);\n\"Thence, to Point ‘12’ (Peak of Mt. Busa);\n\"Thence, following the ridge in a northwesterly direction till it meets the head and/or extremities of Sepaka River to be known as point ‘13’;\n\"Thence, following the course of the Sepaka River in a north easterly direction to Point ‘14’ (junction of Allah River and Sepaka River);\n\"Thence, following the course of the Allah River in a Southeasterly direction to Point ‘15’ (intersection of Allah River and Southwestern corner of Lot No. 2443, PLS-214-D-9, Barrio 11, Map of Bañga, Province of Cotabato);\n\"Thence, following the farm road in a northeasterly direction to the National Highway, thence following the Dimacali Road to Point ‘16’ northeasterly corner of Lot No. 216, PLS-214-D, Lasedeco Survey, Barrio 11, Map of Bañga, Province of Cotabato);\n\"Thence, following the farm road in a Southeasterly direction to Point ‘17’ (southeastern corner of Lot No. 232, PLS-214-D-8, Barrio 8, Map of Bañga, Province of Cotabato);\n\"Thence, following the farm road in a northeasterly direction to Point ‘18’ (northwestern corner of Lot No. 110, PLS-214-D-8, Map of Bañga, Province of Cotabato);\n\"Thence, following the farm road in a southeasterly direction to Point ‘1’, which is the point of beginning.\""}},{"id":"PH-H3100-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two of the same Act is hereby repealed."}},{"id":"PH-H3100-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1963."}}],"pack":"ph-p44","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Surallah in the Province of Cotabato","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3101"] = {"id":"PH-H3101","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3665_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Funds for the Salary Adjustments of High School Supervisors and Teachers in Provinces and Cities and of Intermediate School Supervisors and Teachers in Cities in Accordance with the Salary Ranges Prescribed by the Wage and Position Classification Office","orig":"An Act Appropriating Funds for the Salary Adjustments of High School Supervisors and Teachers in Provinces and Cities and of Intermediate School Supervisors and Teachers in Cities in Accordance with the Salary Ranges Prescribed by the Wage and Position Classification Office"},"level":"law","status":"active","topics":["labor","education"],"docNumber":"Republic Act No. 3665","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3665_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3101-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of six million pesos is appropriated annually, out of any funds in the National Treasury not otherwise appropriated, as aid to provincial, municipal and city governments to effect salary adjustments and/or increases for supervisors, teachers and other personnel in the public high schools being maintained and operated by such governments, as well as of supervisors, teachers and other personnel in the public intermediate schools being operated and maintained by city governments in accordance with the salary ranges prescribed by the Wage and Position Classification Office."}},{"id":"PH-H3101-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1963."}}],"pack":"ph-p44"};
  FT["PH-H3102"] = {"id":"PH-H3102","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1963/ra_3709_1963.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将苏禄省因达南市镇因达南小学的名称变更为Panglima Indanan中央小学的法案","en":"An Act Changing the Name of Indanan Elementary School in the Municipality of Indanan, Province of Sulu, to Panglima Indanan Central Elementary School","orig":"An Act Changing the Name of Indanan Elementary School in the Municipality of Indanan, Province of Sulu, to Panglima Indanan Central Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3709","issuingBody":"Congress of the Philippines","promulgatedDate":"1963-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1963/ra_3709_1963.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3102-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Indanan Elementary School in the Municipality of Indanan, Province of Sulu, is hereby changed to Panglima Indanan Central Elementary School."}},{"id":"PH-H3102-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1963."}}],"pack":"ph-p44","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Indanan Elementary School in the Municipality of Indanan, Province of Sulu, to Panglima Indanan Central Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
